import {readFile,mkdir,writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
const root=path.dirname(fileURLToPath(import.meta.url));
const core=await readFile(path.join(root,'..','reliability.js'),'utf8');
const reliable=(await readFile(path.join(root,'reliable.js'),'utf8')).replace(/^import[^\n]*\n/gm,'').replace(/^export (?=(?:async )?function |const )/gm,'');
let worker=(await readFile(path.join(root,'index.js'),'utf8')).replace(/^import[^\n]*\n/gm,'').replace(/^[ \t]*__test,\r?\n/gm,'').replace(/^\/\/# sourceMappingURL=.*$/gm,'');
const sourceArg=process.argv.indexOf('--sources');
if(sourceArg!==-1){
  const sourcePath=process.argv[sourceArg+1];if(!sourcePath)throw new Error('Missing private source JSON path');
  const sources=JSON.parse(await readFile(sourcePath,'utf8'));
  if(!sources||Array.isArray(sources)||Object.values(sources).some(value=>typeof value?.text!=='string'||value.text.length<100))throw new Error('Invalid lesson source objects');
  worker=worker.replace('var LESSON_SOURCES = {};',`var LESSON_SOURCES = ${JSON.stringify(sources)};`);
  console.log(`Embedded ${Object.keys(sources).length} private lesson sources. Do not publish the generated Worker as frontend assets.`);
}
const output=path.join(root,'dist','worker.mjs');
await mkdir(path.dirname(output),{recursive:true});
await writeFile(output,`// Ra đề GDCD V2.5.9 · single-file Worker · generated by build.mjs\n${core}\n${reliable}\n${worker}`);
console.log(`Built ${output}`);
